package com.example.control;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.time.*;
import java.util.*;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.JdbcTransactionManager;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.server.ResponseStatusException;
/** 専用DBの限定ユーザー、合成管理インスタンスだけを使用する。 */
@EnabledIfEnvironmentVariable(named="OA_ACCEPTANCE_TEST",matches="true")
class IsolatedMembersStorageTest {
    HikariDataSource source;JdbcTemplate jdbc;JdbcTransactionManager manager;ConsoleMembers members;ConsoleStore store;OperatorSettings owner;MemberSecrets secrets;IsolatedControlStorageTest.TestClock clock;final String password="Member-password-123!";
    @BeforeEach void setup()throws Exception{source=IsolatedConsoleDatabase.source(2);jdbc=new JdbcTemplate(source);manager=new JdbcTransactionManager(source);clock=new IsolatedControlStorageTest.TestClock();owner=new OperatorSettings();owner.setOperatorId(UUID.randomUUID().toString());owner.setLoginId("qa_"+UUID.randomUUID().toString().substring(0,8));owner.setPasswordHash(OperatorCrypto.encoder().encode(password));secrets=new MemberSecrets(Base64.getEncoder().encodeToString(new byte[32]));owner.setTotpSecret(secrets.totp());members=new ConsoleMembers(jdbc,owner,clock,secrets,mock(ConsoleEvidence.class),manager);members.registerOwner();store=new ConsoleStore(jdbc,owner,clock,manager);store.setMembers(members);asOwner();}
    @AfterEach void retire(){try{if(jdbc!=null && owner!=null)jdbc.update("UPDATE security_console_operator SET active=0,delete_flag=1,deleted_at=CURRENT_TIMESTAMP(6),invitation_hash=NULL,totp_secret_enc=NULL,password_hash=NULL,auth_version=auth_version+1 WHERE owner_id=?",owner.getOperatorId());}finally{SecurityContextHolder.clearContext();ConsoleRequestContext.clear();if(source!=null)source.close();}}
    String otp(String secret){return Totp.code(secret,clock.instant().getEpochSecond()/30,6);}
    void auth(ConsoleIdentity id){SecurityContextHolder.getContext().setAuthentication(UsernamePasswordAuthenticationToken.authenticated(id,null,List.of(new SimpleGrantedAuthority("ROLE_"+id.role()))));ConsoleRequestContext.begin("qa-source-"+owner.getOperatorId());clock.next();}
    void asOwner(){auth(new ConsoleIdentity(owner.getOperatorId(),owner.getLoginId()));clock.next();}
    ConsoleMembers.Registration invite(String role){return members.create("staff_"+UUID.randomUUID().toString().substring(0,8),"試験担当者",role,"合成人員の登録試験",otp(owner.getTotpSecret()));}
    String loginId(String id){return jdbc.queryForObject("SELECT login_id FROM security_console_operator WHERE id=?",String.class,id);}
    String seed(String id){return secrets.decrypt(owner.getOperatorId(),id,jdbc.queryForObject("SELECT totp_secret_enc FROM security_console_operator WHERE id=?",String.class,id));}
    ConsoleMembers.Setup bind(ConsoleMembers.Registration invite){var setup=members.start(loginId(invite.id()),invite.token(),password);assertNotNull(setup);assertTrue(members.confirm(setup,otp(seed(invite.id()))));return setup;}
    ConsoleIdentity enabled(String role){var invite=invite(role);bind(invite);asOwner();members.change(invite.id(),"enable",null,null,"本人確認済み",otp(owner.getTotpSecret()));clock.next();var result=members.login(loginId(invite.id()),password,otp(seed(invite.id())));assertTrue(result.accepted());return result.identity();}
    @Test void invitationIsOnceAndPendingMemberCannotLoginUntilOwnerEnables(){var invite=invite("OPERATOR");var setup=members.start(loginId(invite.id()),invite.token(),password);assertNotNull(setup);assertNull(members.start(loginId(invite.id()),invite.token(),password));assertFalse(members.login(loginId(invite.id()),password,otp(seed(invite.id()))).accepted());assertTrue(members.confirm(setup,otp(seed(invite.id()))));assertFalse(members.login(loginId(invite.id()),password,otp(seed(invite.id()))).accepted());assertFalse(members.list().toString().contains(invite.token()));assertFalse(members.list().getFirst().containsKey("password_hash"));assertFalse(members.list().getFirst().containsKey("totp_secret_enc"));}
    @Test void rolesCannotSelfElevateOrReleaseButOperatorCanRequestReview(){var actor=enabled("OPERATOR");auth(actor);assertThrows(ResponseStatusException.class,()->members.create("evil_admin","試験","OWNER","提権試験",otp(seed(actor.operatorId()))));assertThrows(ResponseStatusException.class,()->members.list());assertThrows(ResponseStatusException.class,()->store.source("a".repeat(64),null,"解除試験",otp(seed(actor.operatorId()))));store.requestReview("SOURCE_RELEASE","a".repeat(64),null,"解除を依頼する試験",otp(seed(actor.operatorId())));assertEquals(1,store.reviews().size());asOwner();assertEquals(1,store.reviews().size());store.review(((Number)store.reviews().getFirst().get("id")).longValue(),false,"対象再確認のため却下",otp(owner.getTotpSecret()));assertEquals("REJECTED",store.reviews().getFirst().get("state"));}
    @Test void disableAndPermissionChangeInvalidateExistingIdentityAndReinviteRevokesOldSeed(){var actor=enabled("OPERATOR");assertTrue(members.valid(actor));asOwner();members.change(actor.operatorId(),"edit","試験担当者","OBSERVER","監視専用へ変更",otp(owner.getTotpSecret()));assertFalse(members.valid(actor));asOwner();members.change(actor.operatorId(),"disable",null,null,"退任試験",otp(owner.getTotpSecret()));assertFalse(members.login(actor.loginId(),password,otp(seed(actor.operatorId()))).accepted());asOwner();var reinvite=members.change(actor.operatorId(),"reinvite",null,null,"本人確認後の認証器再発行",otp(owner.getTotpSecret()));assertNull(jdbc.queryForObject("SELECT totp_secret_enc FROM security_console_operator WHERE id=?",String.class,actor.operatorId()));assertNotNull(members.start(actor.loginId(),reinvite.token(),password));}
    @Test void unknownLoginDoesNotLockOwnerAndOtherInstancesAreRejected(){for(int i=0;i<5;i++)assertFalse(members.login("does_not_exist","incorrect","000000").accepted());assertEquals(0,jdbc.queryForObject("SELECT failed_attempts FROM security_console_operator WHERE id=?",Integer.class,owner.getOperatorId()));assertTrue(members.login(owner.getLoginId(),password,otp(owner.getTotpSecret())).accepted());var other=new ConsoleIdentity(UUID.randomUUID().toString(),"other","OWNER",0);assertFalse(members.valid(other));asOwner();assertThrows(ResponseStatusException.class,()->members.change(owner.getOperatorId(),"delete",null,null,"自己削除を拒否する試験",otp(owner.getTotpSecret())));assertEquals(1,jdbc.queryForObject("SELECT active FROM security_console_operator WHERE id=?",Integer.class,owner.getOperatorId()));}
    @Test void observerCannotOperateOrRequestAndPasswordChangeRevokesAllSessions(){var actor=enabled("OBSERVER");auth(actor);assertThrows(ResponseStatusException.class,()->members.require("OPERATE",false));assertThrows(ResponseStatusException.class,()->members.require("REVIEW_REQUEST",false));assertEquals(actor,members.require("READ",false));members.password(password,"New-member-pass123!",otp(seed(actor.operatorId())));assertFalse(members.valid(actor));}
    @Test void expiredInvitationSetupAndUnconfirmedDisableCannotBeEnabled(){var invite=invite("OPERATOR");clock.time=clock.time.plusSeconds(86401);assertNull(members.start(loginId(invite.id()),invite.token(),password));asOwner();var second=invite("OPERATOR");var setup=members.start(loginId(second.id()),second.token(),password);clock.time=clock.time.plusSeconds(601);assertThrows(ResponseStatusException.class,()->members.setup(setup));asOwner();members.change(second.id(),"disable",null,null,"期限切れの登録を停止",otp(owner.getTotpSecret()));asOwner();assertThrows(ResponseStatusException.class,()->members.change(second.id(),"enable",null,null,"未登録は有効化不可",otp(owner.getTotpSecret())));}
    @Test void auditFailureRollsBackInvitationAndDoesNotEnableMember(){var broken=mock(ConsoleEvidence.class);doThrow(new org.springframework.dao.DataAccessResourceFailureException("synthetic")).when(broken).record(any());var tested=new ConsoleMembers(jdbc,owner,clock,secrets,broken,manager);long before=jdbc.queryForObject("SELECT COUNT(*) FROM security_console_operator WHERE owner_id=?",Long.class,owner.getOperatorId());assertThrows(org.springframework.dao.DataAccessResourceFailureException.class,()->tested.create("qa_no_commit","試験","OPERATOR","監査障害試験",otp(owner.getTotpSecret())));assertEquals(before,jdbc.queryForObject("SELECT COUNT(*) FROM security_console_operator WHERE owner_id=?",Long.class,owner.getOperatorId()));}
    @Test void operatorCannotShortenOwnerRestrictionAndOwnerApprovalUpdatesSyntheticSource(){var actor=enabled("OPERATOR");String target=OperatorCrypto.hash("qa-member-source:"+owner.getOperatorId());jdbc.update("INSERT INTO security_login_attempt(scope,key_hash,window_start,blocked_until) VALUES('SOURCE',?,?,?)",target,java.sql.Timestamp.valueOf(members.now()),java.sql.Timestamp.valueOf(members.now().plusHours(24)));try{auth(actor);assertEquals(403,assertThrows(ResponseStatusException.class,()->store.source(target,15,"制限短縮を拒否する試験",otp(seed(actor.operatorId())))).getStatusCode().value());clock.next();store.requestReview("SOURCE_RELEASE",target,null,"合成接続元の解除申請",otp(seed(actor.operatorId())));asOwner();var id=((Number)store.reviews().getFirst().get("id")).longValue();store.review(id,true,"最高管理者による合成制限の解除",otp(owner.getTotpSecret()));assertNull(jdbc.queryForObject("SELECT blocked_until FROM security_login_attempt WHERE scope='SOURCE' AND key_hash=?",java.sql.Timestamp.class,target));assertEquals("APPROVED",store.reviews().getFirst().get("state"));}finally{jdbc.update("UPDATE security_login_attempt SET blocked_until=NULL WHERE scope='SOURCE' AND key_hash=?",target);}}
    @Test void progressiveProtectionKeepsIdentityRevokedAfterOwnerReleasesWithoutChangingSecrets(){
        var actor=enabled("OPERATOR");String secret=seed(actor.operatorId());String hash=jdbc.queryForObject("SELECT password_hash FROM security_console_operator WHERE id=?",String.class,actor.operatorId());
        for(int tier=0;tier<3;tier++){
            for(int i=0;i<5;i++)members.login(actor.loginId(),"incorrect","000000");
            assertEquals((tier+1)*5,jdbc.queryForObject("SELECT failed_attempts FROM security_console_operator WHERE id=?",Integer.class,actor.operatorId()));
            if(tier==0)clock.time=clock.time.plusSeconds(900);
            if(tier==1)clock.time=clock.time.plusSeconds(3600);
        }
        assertFalse(members.valid(actor));assertTrue(members.login(actor.loginId(),password,otp(secret)).protectedLogin());
        clock.time=clock.time.plusSeconds(90000);assertTrue(members.login(actor.loginId(),password,otp(secret)).protectedLogin());
        asOwner();members.change(actor.operatorId(),"release",null,null,"本人確認済みの合成担当者を解除",otp(owner.getTotpSecret()));
        assertFalse(members.valid(actor));assertEquals(hash,jdbc.queryForObject("SELECT password_hash FROM security_console_operator WHERE id=?",String.class,actor.operatorId()));assertEquals(secret,seed(actor.operatorId()));
        clock.next();var fresh=members.login(actor.loginId(),password,otp(secret));assertTrue(fresh.accepted());assertTrue(members.valid(fresh.identity()));
    }
    @Test void protectedOwnerCannotBeReleasedThroughMemberAdministration(){
        for(int tier=0;tier<3;tier++){for(int i=0;i<5;i++)members.login(owner.getLoginId(),"incorrect","000000");if(tier==0)clock.time=clock.time.plusSeconds(900);if(tier==1)clock.time=clock.time.plusSeconds(3600);}
        assertTrue(members.login(owner.getLoginId(),password,otp(owner.getTotpSecret())).protectedLogin());
        asOwner();assertThrows(ResponseStatusException.class,()->members.change(owner.getOperatorId(),"release",null,null,"本人解除は本機保守のみ",otp(owner.getTotpSecret())));
        assertEquals(1,jdbc.queryForObject("SELECT login_protected FROM security_console_operator WHERE id=?",Integer.class,owner.getOperatorId()));
    }
}
